function validate([n, lights, requirement]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n must be from 1 to 10^5.';
  if (!Array.isArray(lights) || lights.length < 1 || lights.length > 100000) return 'lights needs 1 to 10^5 lamps.';
  for (const lamp of lights) {
    if (!Array.isArray(lamp) || lamp.length !== 2) return 'Each lamp is a pair [position, range].';
    if (!Number.isInteger(lamp[0]) || lamp[0] < 0 || lamp[0] >= n) return 'Each lamp position is from 0 to n - 1.';
    if (!Number.isInteger(lamp[1]) || lamp[1] < 0 || lamp[1] > 100000) return 'Each lamp range is from 0 to 10^5.';
  }
  if (!Array.isArray(requirement) || requirement.length !== n) return 'requirement must have exactly n values.';
  if (requirement.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each requirement is from 0 to 10^5.';
  return null;
}

