function meetRequirement(n, lights, requirement) {
  let answer = 0;
  for (let p = 0; p < n; p++) {
    let lit = 0;
    for (const lamp of lights) if (Math.abs(p - lamp[0]) <= lamp[1]) lit++;
    if (lit >= requirement[p]) answer++;
