function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(1500, 2000);
    const count = int(1000, 2000);
    const wide = rand() < 0.3;
    const lights = Array.from({ length: count }, () => [int(0, n - 1), wide && rand() < 0.2 ? int(0, 100000) : int(0, 60)]);
    const top = Math.floor(count * 0.1) + 5;
    const requirement = Array.from({ length: n }, () => int(0, top));
    return [n, lights, requirement];
  }
  const n = int(1, 8);
  const count = int(1, 6);
  const lights = Array.from({ length: count }, () => [int(0, n - 1), rand() < 0.15 ? 100000 : int(0, 4)]);
  const requirement = Array.from({ length: n }, () => int(0, count + 1));
  return [n, lights, requirement];
}
